import { createAsyncThunk } from "@reduxjs/toolkit";

export const fetchGetUser = createAsyncThunk(
    "user/fetchGetUser", 
    async ()=> {
        const result= await fetch("http://localhost:8000/api/register")
        const jsonResult = await result.json()
        return jsonResult
    }
)


export const fetchGetLogedUser = createAsyncThunk(
    "user/fetchGetLogedUser", 
    async ()=> {
        const result= await fetch("http://localhost:3005/Loged_User")
        const jsonResult = await result.json()
        return jsonResult
    }
)


export const fetchGetNewsLent = createAsyncThunk(
    "news/fetchGetNewsLent", 
    async ()=> {
        const result= await fetch("http://localhost:3005/News_Lent")
        const jsonResult = await result.json()
        return jsonResult
    }
)
export const fetchProfileUser = createAsyncThunk(
    "user/fetchProfileUser",
    async (_, thunkAPI) => {
      try {
        const token = localStorage.getItem("token");
  
        const res = await fetch("http://localhost:8000/api/profile", {
          method: "GET",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        });
  
        if (!res.ok) {
          throw new Error("Unauthorized");
        }
  
        const jsonResult = await res.json();
        return jsonResult;
      } catch (err) {
        return thunkAPI.rejectWithValue(err.message);
      }
    }
  );
